			//================================================================================= 

			var util = createCommonUtil();
			var isSave = false;
			var stateType =  "";
			var loginInfo = util.Auth;
			var modifyAuth = false;
			var aprvAuth = false;
			var popHost = "";
			//=================================================================================
			// [Function]
			//================================================================================= 	

			/**
			 * 목록 데이터 조회 서브미션 호출
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doList(psStatus) {
			    
			    //조회 서브미션 호출
			    util.Submit.send(app, "subList", function(pbSuccess) {
			        app.lookup("cmb4").focus();
			        if (pbSuccess) {
			            if (psStatus == "save") {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			                
			                if((app.lookup("cmb1").text == null || app.lookup("cmb1").text == '') && popHost == 'bgtPrfmncList'){
			                    app.lookup("cmb1").addItem(new cpr.controls.Item(app.lookup("dsBgtImplInfo").getValue(0, "RESRCE_NM"), app.lookup("dsBgtImplInfo").getValue(0, "RESRCE_NO")));
			                }
			                
			            }
			            btnVisibility('read');
			            checkAuth();
			            app.lookup("grpData").redraw();
			        }
			    });
			}


			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave() {
			    
			    // 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
			    if (!util.Grid.isModified(app, "grdId", "MSG")) return false;
			    
			    // 그리드 내 컬럼 유효성 체크
			    if (!util.validate(app, "grdId")) return false;
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			            doList("save");
			        }
			    });
			}


			/**
			 * 접근 상태에 따른 하단의 버튼 숨김 처리
			 * @param {any} mode - 접근 상태(등록,조회,수정)
			 */
			function btnVisibility() {
			    var btnSave = app.lookup("btnSave");
			    var btnRevise = app.lookup("btnRevise");
			    var btnDelete = app.lookup("btnDelete");
			    var btnRestore = app.lookup("btnRestore");
			    
			    if (stateType == 'add') {
			        //등록
			        btnSave.visible = true;
			        btnRestore.visible = false;
			        btnDelete.visible = false;
			        btnRevise.visible = false;
			    } else if (stateType == 'read') {
			        //조회
			        btnSave.visible = false;
			        btnRestore.visible = false;
			        //상태가 대기 또는 반려일 경우 해당 예산실적 신청한 신청자만 수정 가능
			        if((app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') == '0' 
			             || app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') == '5')
			             && util.Auth.getUserInfo(app,"ENFSN_NO") == app.lookup("dsBgtImplInfo").getValue(0, "APLY_PIC_NO")){
			            //승인상태가 대기 또는 수정요청 상태일 경우
			            btnDelete.visible = true;
			            btnRevise.visible = true;
			        }else if((loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '310' || loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '320')
			                 && loginInfo.getUserInfo(app,"INST_TYPE_SE_CD") == '6'
			                 && app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') != '0'
			                 && app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') != '5'){
			            btnDelete.visible = true;
			            btnRevise.visible = true;
			            aprvAuth = true;
			        }else{
			            btnDelete.visible = false;   
			            btnRevise.visible = false;   
			        }
			        //승인/반려일 경우 신청자 수정 불가
			        if(app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') == '2' || app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') == '3'){
			            //|| app.lookup("dsBgtImplInfo").getValue(0, 'APRV_STTS_SE_CD') == '5'){
			            if(loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '310'){
			                btnRevise.visible = true;
			                btnDelete.visible = false;
			            }else{
			                btnDelete.visible = false;
			                btnRevise.visible = false;
			            }
			        }
			    } else {
			        //수정
			        btnSave.visible = true;
			        btnRestore.visible = true;
			        btnDelete.visible = false;
			        btnRevise.visible = false;
			    }
			}


			/**
			 * CRUD 권한에 따른 화면 구성
			 ** @param {"CREATE" | "0" | "1" | else} psType 게시글 상세 조회 타입
			 */
			function checkAuth() {
			    var aprvSttsSeCd = app.lookup("dsBgtImplInfo").getValue(0, "APRV_STTS_SE_CD");
			    var cmb3 = app.lookup("cmb3");
			    var cmb4 = app.lookup("cmb4");
			    var dsResrce = app.lookup("dsResrce");
			    
			    if(stateType == 'add'){
			        cmb3.setFilter("value == '0' || value == '1'");
			        cmb3.selectItem(0);
			        
			        if (ValueUtil.isNull(cmb4.getItemByValue(moment().year()))) {
			            cmb4.selectItem(0);
			        } else {
			            cmb4.selectItemByValue(moment().year());
			        }
			                
			        app.lookup("txa1").readOnly = true;
			        
			        app.lookup("cmb1").selectItem(0);
			        app.lookup("cmb2").selectItem(0);
			        app.lookup("opt12").value = util.Auth.getUserInfo(app,"USER_NM");
			        app.lookup("opt13").value = moment().format("YYYY-MM-DD");
			        app.lookup("nbe1").readOnly = false;
			        app.lookup("opt11").value = loginInfo.getUserInfo(app, "INST_NM");
			        
			//        console.log("fwefew44 : " + JSON.stringify(app.lookup("dsResrce").getRowDataRanged()));
			//        console.log("123 :  "+ app.lookup("cmb4").value);
			//        console.log("123 :  "+ loginInfo.getUserInfo(app,"INST_NO"));
			        app.lookup("dsResrce").setFilter("SRVC_RESRCE_LCLAS_SE_CD != '01' && BIZ_YR == " + app.lookup("cmb4").value + "&& INST_NO == " + loginInfo.getUserInfo(app,"INST_NO"));
			//        console.log("fwefew55 : " + JSON.stringify(app.lookup("dsResrce").getRowDataRanged()));
			        
			    }else if(stateType == 'modify'){
			        
			        switch(aprvSttsSeCd){
			        	case '0' :
			        		cmb3.setFilter("value == '1'");
			        		app.lookup("txa1").readOnly = true;
			        		break;
			        	case '1' :
			        	case "4" :
			                cmb3.setFilter("value != '0' && value != '1'");
			                if((loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '310' || loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '320')
			                    && loginInfo.getUserInfo(app,"INST_TYPE_SE_CD") == '6'){
			                        app.lookup("txa1").readOnly = false;
			                }else{
			                    app.lookup("txa1").readOnly = true;
			                }
			                break;
			            case '2' :
			                cmb3.setFilter("value == '3' || value == '5'");
			                app.lookup("txa1").readOnly = false;
			                break;
			            case '3' :
			                cmb3.setFilter("value == '2' || value == '5'");
			                app.lookup("txa1").readOnly = false;
			                break;
			            case '5' :
			                cmb3.setFilter("value == '1'");
			                app.lookup("txa1").readOnly = true;
			                break;
			        	default :
			        		break;
			        }
			        if((loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '310' || loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '320')
			             && loginInfo.getUserInfo(app,"INST_TYPE_SE_CD") == '6'){
			            if(util.Auth.getUserInfo(app,"ENFSN_NO") == app.lookup("dsBgtImplInfo").getValue(0, "APLY_PIC_NO")){
			                app.lookup("grp2").readOnly = false;
			                app.lookup("grp5").readOnly = false;
			            }else{
			                app.lookup("grp2").readOnly = true;
			                app.lookup("grp5").readOnly = true;
			            }
			            app.lookup("grp4").readOnly = false;
			            app.lookup("txa1").readOnly = false;
			        }
			    }
			    if((loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '310' || loginInfo.getUserInfo(app, "GROUP_AUTHRT_SE_CD") == '320')
			        && loginInfo.getUserInfo(app,"INST_TYPE_SE_CD") == '6'){
			        dsResrce.setFilter("SRVC_RESRCE_LCLAS_SE_CD != '01' && BIZ_YR == " + app.lookup("cmb4").value);
			        
			    }else{
			        if(loginInfo.getUserInfo(app,"INST_TYPE_SE_CD") == '8'){
			            app.lookup("dsResrce").setFilter("SRVC_RESRCE_LCLAS_SE_CD != '01' && BIZ_YR == " + app.lookup("cmb4").value + "&& INST_NO == " + loginInfo.getUserInfo(app,"INST_NO"));
			        }
			    }
			}

			//=================================================================================
			// [Control Event Function]
